def load_binary_table(csv_path=None, fallback=True):
    """
    Load the binary oxide MAPLE reference table.

    Priority:
    1. CSV from a MaplePy batch run on binary CIFs (if csv_path given)
    2. Fallback dict above

    Returns
    -------
    dict  {reduced_formula: maple_kcal_mol}
    pd.DataFrame  for display
    """
    lookup = {}
    rows = []

    if csv_path is not None and Path(csv_path).exists():
        df = pd.read_csv(csv_path)
        print(f"Loaded binary reference from {csv_path}")
        name_col = 'compound' if 'compound' in df.columns else 'formula'
        for _, r in df.iterrows():
            formula = r[name_col]
            maple = r['total_maple'] if 'total_maple' in df.columns \
                    else r.get('maple_kcal_mol')
            if pd.notna(maple):
                lookup[formula] = float(maple)
                rows.append({"formula": formula,
                             "maple_kcal_mol": float(maple),
                             "source": "ICSD CIF batch"})
        print(f"  {len(lookup)} binaries loaded from CSV.")

    if fallback:
        n_added = 0
        for formula, (maple, stype, source) in BINARY_MAPLE_FALLBACK.items():
            if formula not in lookup:
                lookup[formula] = maple
                rows.append({"formula": formula,
                             "maple_kcal_mol": maple,
                             "source": source})
                n_added += 1
        if n_added > 0:
            print(f"  {n_added} binaries added from fallback table.")

    df_out = pd.DataFrame(rows).sort_values("formula").reset_index(drop=True)
    print(f"  Total binary references: {len(lookup)}")
    return lookup, df_out


# ── The released reference table is the source ──────────────────────────────
#
# v1.2: BINARY_MAPLE_FALLBACK above is a 104-entry dict written inline. The
# released JSON has 112 - the extra eight are the oxyanion formers added for
# the borosulfate work, which the notebook never received. Measured formula by
# formula, no VALUE disagrees between the two, but the membership already
# does, and the copy the community downloads was not the copy the analysis
# used.
#
# The JSON is now read first. The inline dict remains for when the file is
# absent, and the guard below compares the two wherever they overlap: a value
# that has drifted stops the run and names the formula, rather than one copy
# quietly winning.

def load_binary_reference(path=None):
    """
    The binary oxide reference table, from the released JSON.

    Returns (lookup, source_string). Falls back to the inline dict only when
    no JSON can be found, and says so.
    """
    import json as _json
    from pathlib import Path as _Path

    _names = ('binary_oxide_maple_reference_v1_1.json',
              'binary_oxide_maple_reference.json')
    _dirs = ('data', '.', '..')
    _cands = ([_Path(path)] if path else
              [_Path(d) / n for d in _dirs for n in _names])

    for _p in _cands:
        if not _p.is_file():
            continue
        with open(_p, 'r', encoding='utf-8') as _f:
            _d = _json.load(_f)
        _lookup = {e['formula']: float(e['maple_kcal_mol'])
                   for e in _d['entries']}
        return _lookup, str(_p.resolve())

    if path:
        raise FileNotFoundError(f'binary reference table not found: {path}')
    return ({f: v[0] for f, v in BINARY_MAPLE_FALLBACK.items()},
            'INLINE FALLBACK - the released JSON was not found')


BINARY_REFERENCE_PATH = _HOPPER_REFERENCE_PATH   # maplepy package: the bundled table
#    # set to override the search

_json_lookup, _binary_source = load_binary_reference(BINARY_REFERENCE_PATH)

# THE GUARD. Two copies of one table are safe only while something checks
# them. Where a formula is in both, the values must agree.
_drift = [(f, BINARY_MAPLE_FALLBACK[f][0], _json_lookup[f])
          for f in sorted(set(BINARY_MAPLE_FALLBACK) & set(_json_lookup))
          if abs(BINARY_MAPLE_FALLBACK[f][0] - _json_lookup[f]) > 1e-6]
if _drift:
    raise AssertionError(
        'the inline table and the released JSON disagree on '
        + ', '.join(f'{f} ({a} vs {b})' for f, a, b in _drift[:5])
        + f'{" and others" if len(_drift) > 5 else ""}. '
        'One of them is stale; decide which before running.')

print(f'  binary reference: {len(_json_lookup)} entries from {_binary_source}')

# ── Which entries are estimates ────────────────────────────────────────
#
# v1.2.9: 23 of the 112 values are estimates, interpolated within a structure
# type or set by hand, and none has a published or computed source; Cu2O's
# recorded source, a MaplePy calculation at a = 4.270 A, gives 797.9 rather
# than 730.0 and is marked unsourced in the JSON (sourced: false). They are
# kept, so that results made with them can be reproduced, and every
# decomposition that uses one says so (`estimated_binaries`). Nothing is
# reclassified on that account: a residual resting on an estimate is a
# residual against a weaker reference, and the reader is told which.
def estimated_binaries(source_path):
    """The formulae whose reference value is an estimate, or unsourced.

    From the released JSON's `source` and `sourced` fields where the table
    was read from it (Cu2O is unsourced, not estimated);
    from the inline labels where it was not.
    """
    import json as _json
    from pathlib import Path as _Path
    _p = _Path(source_path)
    if _p.is_file():
        with open(_p, 'r', encoding='utf-8') as _f:
            return {e['formula'] for e in _json.load(_f)['entries']
                    if e.get('source') == 'estimated'
                    or e.get('sourced') is False}
    return {f for f, (_v, _t, _s) in BINARY_MAPLE_FALLBACK.items()
            if _s.lower().startswith(('estimated', 'interpolated'))}


ESTIMATED_BINARIES = estimated_binaries(_binary_source)
print(f'  estimated or unsourced: {len(ESTIMATED_BINARIES)} entries')
print(f'  inline fallback:  {len(BINARY_MAPLE_FALLBACK)} entries, '
      f'{len(set(_json_lookup) - set(BINARY_MAPLE_FALLBACK))} of the released '
      f'entries not in it, no value in disagreement')

# To use your own ICSD batch results instead, set BINARY_CSV below.
BINARY_CSV = None   # e.g. Path("binary_oxides/maple_summary.csv")

BINARY_MAPLE, df_binary = load_binary_table(csv_path=BINARY_CSV)
# the released table wins over the inline fallback for anything it carries
BINARY_MAPLE.update(_json_lookup)
display(df_binary)